/**
 * @method
 * @name scwin.selectedCorp
 * @author Inswave
 * @date 2026. 09. 29
 * @param co_cd co_nm
 * @returns
 * @hidden N
*/
scwin.selectedCorp = function (co_cd, co_nm) {
    /* sdd-asis-lifecycle:begin selectedCorp — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.InputForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent("dma_clickSearchListReq").get("itemCd")) > 0) {
        (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById($c.util.getComponent("dma_clickSearchListReq").get("itemCd"))) || { setValue: function () {} }).setValue(co_cd);
    }
    if ($c.str.getByteLength($c.util.getComponent("dma_clickSearchListReq").get("itemNm")) > 0) {
        (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById($c.util.getComponent("dma_clickSearchListReq").get("itemNm"))) || { setValue: function () {} }).setValue(co_nm);
    }
    if ($c.util.getComponent("dma_clickSearchListReq").get("itemNm") === 'bnd_majagnt_com_nm') {
        if (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById('bnd_apct_tp_cd')) && ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById('bnd_apct_tp_cd')).getValue) ? ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById('bnd_apct_tp_cd')).getValue() : '') === '2') {
            (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById('rep_majagnt_com_nm')) && ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById('rep_majagnt_com_nm')).setValue ? ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById('rep_majagnt_com_nm')).setValue(co_nm) : void (co_nm));
        }
    }
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.clickSearchList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.clickSearchList = async function () {
    /* sdd-asis-lifecycle:begin fn_clickSearchList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.InputForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_searchWord').getValue()) == 0) {
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
        await $c.win.alert('검색조건을 입력바랍니다.');
        event.keyCode = 0;
        return false;
    } else {
        $c.util.getComponent('ipt_method').setValue("loadIndSearchData");
        fm.action = "/common/InstSearch.do";
        fm.target = "_self";
        await scwin.tx_fn_clickSearchList();
        event.keyCode = 0;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.enterSearchList
 * @author Inswave
 * @date 2026. 09. 29
 * @param event
 * @returns
 * @hidden N
*/
scwin.enterSearchList = async function (event) {
    /* sdd-asis-lifecycle:begin fn_enterSearchList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.InputForm || { elements: [] });
    if (event && $c.util.getKeyCode(event) == 13) {
        event.keyCode = 0;
        if ($c.str.getByteLength($c.util.getComponent('ipt_searchWord').getValue()) == 0) {
            console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
            await $c.win.alert('검색조건을 입력바랍니다.');
            return false;
        } else {
            replacePercent($c.util.getComponent('ipt_searchWord'));
            $c.util.getComponent('ipt_method').setValue("loadIndSearchData");
            fm.action = "/common/InstSearch.do";
            fm.target = "_self";
            await scwin.tx_fn_enterSearchList();
        }
    }
    /* sdd-asis-lifecycle:end */
};
